export const REGION_GEO_BY_SLUG = new Map(REGION_GEO.map((r) => [r.slug, r]));


/** Scale and offset that fit a bbox inside VIEWPORT, preserving aspect. */
export function fitBBox(b: BBox) {
  const [bx, by, bw, bh] = b;
  const s = Math.min(VIEWPORT.width / bw, VIEWPORT.height / bh);
  return {
    s,
    x: (VIEWPORT.width - bw * s) / 2 - bx * s,
    y: (VIEWPORT.height - bh * s) / 2 - by * s,
  };
}

/** Atlas point to viewport point under a given fit. */
export function toViewport(pt: [number, number], f: { s: number; x: number; y: number }) {
  return [pt[0] * f.s + f.x, pt[1] * f.s + f.y] as const;
}

export function bboxCentre(b: BBox): [number, number] {
  return [b[0] + b[2] / 2, b[1] + b[3] / 2];
}
